namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }

    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<RecipeCategory> _categories =
    [
        new() { Name = "Breakfast", Description = "Start your day right with morning favorites", Icon = "🥞" },
        new() { Name = "Lunch", Description = "Midday meals to keep you going", Icon = "🥗" },
        new() { Name = "Dinner", Description = "Hearty evening dishes for the whole family", Icon = "🍝" },
        new() { Name = "Desserts", Description = "Sweet treats to satisfy your cravings", Icon = "🍰" },
        new() { Name = "Snacks", Description = "Quick bites for any time of day", Icon = "🍿" },
    ];

    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
                Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "2 tbsp sugar", "2 tsp baking powder", "¼ tsp salt", "2 tbsp melted butter"],
                Steps = ["Mix dry ingredients in a bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Heat a greased skillet over medium heat.", "Pour ¼ cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown.", "Serve with maple syrup and fresh berries."],
                TotalRatingPoints = 18, RatingCount = 4
            },
            new()
            {
                Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Description = "Crisp romaine lettuce with creamy Caesar dressing and croutons.",
                Ingredients = ["1 head romaine lettuce", "½ cup Caesar dressing", "¼ cup Parmesan cheese", "1 cup croutons", "2 anchovy fillets (optional)", "1 lemon"],
                Steps = ["Wash and chop romaine lettuce.", "Toss lettuce with Caesar dressing.", "Add croutons and shaved Parmesan.", "Squeeze fresh lemon juice on top.", "Toss gently and serve immediately."],
                TotalRatingPoints = 8, RatingCount = 2
            },
            new()
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Description = "A rich and savory Italian meat sauce over al dente pasta.",
                Ingredients = ["1 lb ground beef", "1 lb spaghetti", "1 can crushed tomatoes", "1 onion, diced", "3 cloves garlic, minced", "2 tbsp olive oil", "1 tsp dried basil", "Salt and pepper to taste"],
                Steps = ["Cook spaghetti according to package directions.", "Sauté onion and garlic in olive oil.", "Add ground beef and cook until browned.", "Stir in crushed tomatoes and basil.", "Simmer for 20 minutes.", "Season with salt and pepper.", "Serve sauce over spaghetti with grated Parmesan."],
                TotalRatingPoints = 23, RatingCount = 5
            },
            new()
            {
                Id = 4, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Chewy, gooey cookies loaded with chocolate chips.",
                Ingredients = ["2¼ cups flour", "1 cup butter, softened", "¾ cup sugar", "¾ cup brown sugar", "2 eggs", "1 tsp vanilla extract", "1 tsp baking soda", "2 cups chocolate chips"],
                Steps = ["Preheat oven to 375°F (190°C).", "Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour and baking soda.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheets.", "Bake for 9-11 minutes until golden.", "Cool on baking sheet for 5 minutes before transferring."],
                TotalRatingPoints = 15, RatingCount = 3
            },
            new()
            {
                Id = 5, Title = "Guacamole", Category = "Snacks",
                Description = "Fresh and zesty avocado dip, perfect with tortilla chips.",
                Ingredients = ["3 ripe avocados", "1 lime, juiced", "½ tsp salt", "½ cup diced onion", "2 tbsp fresh cilantro", "1 jalapeño, seeded and minced", "1 tomato, diced"],
                Steps = ["Cut avocados in half and remove pits.", "Scoop flesh into a bowl and mash with a fork.", "Stir in lime juice and salt.", "Mix in onion, cilantro, jalapeño, and tomato.", "Taste and adjust seasoning.", "Serve immediately with tortilla chips."],
                TotalRatingPoints = 14, RatingCount = 3
            },
            new()
            {
                Id = 6, Title = "Eggs Benedict", Category = "Breakfast",
                Description = "Poached eggs on English muffins with hollandaise sauce.",
                Ingredients = ["4 eggs", "2 English muffins, split", "4 slices Canadian bacon", "3 egg yolks", "1 tbsp lemon juice", "½ cup melted butter", "Pinch of cayenne"],
                Steps = ["Make hollandaise: whisk egg yolks and lemon juice over double boiler.", "Slowly drizzle in melted butter while whisking.", "Season with cayenne and keep warm.", "Toast English muffins.", "Cook Canadian bacon in a skillet.", "Poach eggs in simmering water with a splash of vinegar.", "Assemble: muffin, bacon, egg, hollandaise.", "Serve immediately."],
                TotalRatingPoints = 9, RatingCount = 2
            },
            new()
            {
                Id = 7, Title = "Chicken Stir-Fry", Category = "Dinner",
                Description = "Quick and colorful stir-fry with tender chicken and crisp vegetables.",
                Ingredients = ["1 lb chicken breast, sliced", "2 cups mixed vegetables", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "2 cloves garlic, minced", "1 tsp ginger, grated", "Cooked rice for serving"],
                Steps = ["Mix soy sauce, sesame oil, and cornstarch for the sauce.", "Heat oil in a wok over high heat.", "Cook chicken until golden, then remove.", "Stir-fry vegetables for 2-3 minutes.", "Return chicken to the wok.", "Pour in sauce and toss to coat.", "Cook until sauce thickens.", "Serve over steamed rice."],
                TotalRatingPoints = 12, RatingCount = 3
            },
        ];
        _nextId = 8;
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipe(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

