arguments.file_text:
@page "/category/{CategoryName}"
@using RecipeHub.Services

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<h1>@category?.Icon @CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <div class="alert alert-info">No recipes in this category yet. <a href="submit">Submit one!</a></div>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="mb-2">
                            <span class="text-warning">@GetStarDisplay(recipe.AverageRating)</span>
                            <small class="text-muted">(@recipe.RatingCount ratings)</small>
                        </div>
                        <a href="recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-2">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public required RecipeService RecipeService { get; set; }

    private List<RecipeHub.Models.Recipe> recipes = [];
    private RecipeHub.Models.RecipeCategory? category;

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(CategoryName);
        category = RecipeService.GetCategories().FirstOrDefault(c =>
            c.Name.Equals(CategoryName, StringComparison.OrdinalIgnoreCase));
    }

    private static string GetStarDisplay(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        return new string('★', fullStars) + new string('☆', 5 - fullStars);
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeHub.Services

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="lead text-muted">@recipe.Description</p>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card mb-4">
                <div class="card-header"><strong>👩‍🍳 Steps</strong></div>
                <div class="card-body">
                    <ol>
                        @foreach (var step in recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <h5>Rate this Recipe</h5>
            <RecipeHub.Components.StarRating RecipeId="recipe.Id" />
        </div>
    </div>

    <a href="category/@recipe.Category" class="btn btn-outline-secondary">← Back to @recipe.Category</a>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipe(RecipeId);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        int star = i;
        <span class="star @(star <= hoverStar ? "star-hover" : "") @(star <= currentRating ? "star-selected" : "")"
              @onmouseover="() => hoverStar = star"
              @onmouseout="() => hoverStar = 0"
              @onclick="() => SubmitRating(star)"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= (hoverStar > 0 ? hoverStar : currentRating) ? "★" : "☆")
