@page "/recipe/{RecipeId:int}"
@using RecipeHub.Services

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="lead text-muted">@recipe.Description</p>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card mb-4">
                <div class="card-header"><strong>👩‍🍳 Steps</strong></div>
                <div class="card-body">
                    <ol>
                        @foreach (var step in recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <h5>Rate this Recipe</h5>
            <RecipeHub.Components.StarRating RecipeId="recipe.Id" />
        </div>
    </div>

    <a href="category/@recipe.Category" class="btn btn-outline-secondary">← Back to @recipe.Category</a>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipe(RecipeId);
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        int star = i;
        <span class="star @(star <= hoverStar ? "star-hover" : "") @(star <= currentRating ? "star-selected" : "")"
              @onmouseover="() => hoverStar = star"
              @onmouseout="() => hoverStar = 0"
              @onclick="() => SubmitRating(star)"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= (hoverStar > 0 ? hoverStar : currentRating) ? "★" : "☆")
        </span>
    }

    @if (submitted)
    {
        <span class="text-success ms-2">✓ Thanks for rating!</span>
    }
    else
    {
        <span class="text-muted ms-2">Click to rate</span>
    }
</div>

@code {
    [Parameter] public required int RecipeId { get; set; }
    [Inject] public required RecipeService RecipeService { get; set; }

    private int currentRating;
    private int hoverStar;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        currentRating = stars;
        submitted = true;
    }
}

